SELECT sr.sr_store_sk, d_ret.d_date AS return_date, SUM(sr.sr_net_loss) AS daily_net_loss, CASE WHEN SUM(sr.sr_net_loss) > 1000 THEN 'High Loss' ELSE 'Normal Loss' END AS loss_category, AVG(t.t_hour) AS avg_return_hour, SUM(SUM(sr.sr_net_loss)) OVER (PARTITION BY sr.sr_store_sk ORDER BY d_ret.d_date ROWS UNBOUNDED PRECEDING) AS cumulative_net_loss, AVG(SUM(sr.sr_net_loss)) OVER (PARTITION BY sr.sr_store_sk ORDER BY d_ret.d_date ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS moving_avg_7d, DENSE_RANK() OVER (ORDER BY SUM(sr.sr_net_loss) DESC) AS store_loss_rank FROM store_returns sr JOIN date_dim d_ret ON sr.sr_returned_date_sk = d_ret.d_date_sk JOIN time_dim t ON sr.sr_return_time_sk = t.t_time_sk LEFT JOIN call_center cc ON cc.cc_open_date_sk = d_ret.d_date_sk GROUP BY sr.sr_store_sk, d_ret.d_date
